import redis, struct
r = redis.Redis()
fmt='>64d'
v1=[1.0]+[0.0]*63
def brief(res):
    rows=[]
    if isinstance(res, dict):
        for x in res.get(b'results',res.get('results',[])):
            rows.append({k.decode() if isinstance(k,bytes) else k: (v.decode()[:24] if isinstance(v,bytes) else v) for k,v in (x.get(b'extra_attributes') or {}).items()})
        return {'total': res.get(b'total_results',res.get('total_results')), 'rows': rows}
    return res
tests = {
 'D knn_ret':   ['FT.SEARCH','test:idx','*=>[KNN 2 @embedding $q]','RETURN',1,'id','PARAMS',2,'q',struct.pack(fmt,*v1),'DIALECT',2],
 'E knn_noret': ['FT.SEARCH','test:idx','*=>[KNN 2 @embedding $q]','PARAMS',2,'q',struct.pack(fmt,*v1),'DIALECT',2],
 'F hybrid':    ['FT.SEARCH','test:idx','*=>[KNN 2 @embedding $q AS vscore]','RETURN',1,'id','PARAMS',2,'q',struct.pack(fmt,*v1),'DIALECT',2],
 'G sortby':    ['FT.SEARCH','test:idx','*=>[KNN 2 @embedding $q]','RETURN',1,'id','SORTBY','__embedding_score','PARAMS',2,'q',struct.pack(fmt,*v1),'DIALECT',2],
 'H dialect3':  ['FT.SEARCH','test:idx','KNN 2 @embedding $q','RETURN',1,'id','PARAMS',2,'q',struct.pack(fmt,*v1),'DIALECT',3],
}
for name,args in tests.items():
    try:
        print(name,'OK',brief(r.execute_command(*args)))
    except Exception as e:
        print(name,'ERR',str(e)[:150])
EOF
